def _scenarios():
    for family, block in (("Math", _MATH), ("Reading", _READING), ("English", _ENGLISH),
                          ("Science", _SCIENCE), ("History", _HISTORY)):
        for row in block.strip().splitlines():
            fields = row.split("|")
            if len(fields) != 9:
                raise ValueError(f"Malformed scenario in {family}: {fields[0]}")
            yield family, fields


def _record(identifier, family, scenario_id, source, question, quote, hint, anchors):
    target = f"EVIDENCE: {quote}\nNEXT: {hint}"
    return {
        "id": identifier, "scenarioId": scenario_id, "family": family,
        "source": source, "question": question, "target": target,
        "expectedAbstention": quote == "insufficient",
        "nextStepAnchors": anchors.split(","),
        "acceptedQuotes": [] if quote == "insufficient" else [quote],
        "messages": [
            {"role": "system", "content": SYSTEM},
            {"role": "user", "content": f"SOURCE: {source}\nQUESTION: {question}"},
            {"role": "assistant", "content": target},
        ],
    }


def training_cases():
    """Return 200 fresh records from 100 source-sharing question contrasts."""
    cases = []
    for family, fields in _scenarios():
        slug, source, question, quote, hint, missing, missing_hint, anchors, missing_anchors = fields
        scenario_id = f"v4-{family.lower()}-{slug}"
        cases.append(_record(f"{scenario_id}-supported", family, scenario_id, source,
                             question, quote, hint, anchors))
        cases.append(_record(f"{scenario_id}-insufficient", family, scenario_id, source,
                             missing, "insufficient", missing_hint, missing_anchors))
    assert len(cases) == 200
    assert len({case["id"] for case in cases}) == 200
    assert len({case["source"] for case in cases}) == 100
    assert Counter(case["family"] for case in cases) == {
        "Math": 40, "Reading": 40, "English": 40, "Science": 40, "History": 40,
    }
    for case in cases:
        for quote in case["acceptedQuotes"]:
            assert quote in case["source"] and len(quote) <= 240
    return cases
